import org.junit.*;
import org.junit.Assert;
import org.junit.Test;
import static org.junit.Assert.*;

public class X7875_NewUnix_equals_TriageGen1Test {

    /**
     * Helper method to set private fields via reflection since 
     * the class doesn't provide setters for version, uid, or gid.
     */
    private void setFields(X7875_NewUnix obj, int version, long uid, long gid) throws Exception {
        Field versionField = X7875_NewUnix.class.getDeclaredField("version");
        versionField.setAccessible(true);
        versionField.set(obj, version);

        Field uidField = X7875_NewUnix.class.getDeclaredField("uid");
        uidField.setAccessible(true);
        // The code uses .equals() on uid, implying it's an object (likely Long or Integer)
        // Based on getUID() returning long, the field is likely a Long wrapper.
        uidField.set(obj, uid);

        Field gidField = X7875_NewUnix.class.getDeclaredField("gid");
        gidField.setAccessible(true);
        gidField.set(obj, gid);
    }

    @Test
    public void testEquals_SameObject() throws Exception {
        X7875_NewUnix obj = new X7875_NewUnix();
        setFields(obj, 1, 1000L, 1000L);

        Assert.assertTrue(obj.equals(obj));
    }












}

